    while (index < parts.Length && parts[index].Split('\n')[0].Trim().EndsWith(":"))
    {
        string[] lines = parts[index].Split(new[] { "\r\n" }, StringSplitOptions.None);
        int h = lines.Length - 1;
        int w = lines[1].Length;
        bool[,] shape = new bool[h, w];

        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                shape[y, x] = lines[y + 1][x] == '#';

        shapes.Add(shape);
        index++;
    }

    int success = 0;

    string rest = string.Join("\r\n\r\n", parts, index, parts.Length - index);
    string[] regionLines = rest.Split(new[] { "\r\n" }, StringSplitOptions.RemoveEmptyEntries);

    foreach (string line in regionLines)
    {
        string[] split = line.Split(':');
        string[] size = split[0].Split('x');

        int W = int.Parse(size[0]);
        int H = int.Parse(size[1]);

        string[] counts = split[1].Trim().Split(' ');

        List<int> pieces = new List<int>();
        for (int i = 0; i < counts.Length; i++)
        {
            int cnt = int.Parse(counts[i]);
            for (int c = 0; c < cnt; c++)
                pieces.Add(i);
        }

        int needed = 0;
        foreach (int p in pieces)
        {
            bool[,] sh = shapes[p];
            for (int y = 0; y < sh.GetLength(0); y++)
                for (int x = 0; x < sh.GetLength(1); x++)
                    if (sh[y, x]) needed++;
        }

        if (needed > W * H)
            continue;

        bool[,] grid = new bool[H, W];

        if (Backtrack(grid, pieces, 0, shapes))
            success++;
    }

    Console.WriteLine(success);

    bool Backtrack(bool[,] grid, List<int> pieces, int pos, List<bool[,]> shapes)
    {
        if (pos == pieces.Count)
            return true;

        int shapeIndex = pieces[pos];
        List<bool[,]> variants = GetVariants(shapes[shapeIndex]);

        foreach (var v in variants)
        {
            int h = v.GetLength(0);
            int w = v.GetLength(1);

            for (int y = 0; y <= grid.GetLength(0) - h; y++)
            {
                for (int x = 0; x <= grid.GetLength(1) - w; x++)
                {
                    if (CanPlace(grid, v, x, y))
                    {
                        Place(grid, v, x, y, true);
                        if (Backtrack(grid, pieces, pos + 1, shapes))
                            return true;
                        Place(grid, v, x, y, false);
                    }
                }
            }
        }
        return false;
    }

    bool CanPlace(bool[,] grid, bool[,] shape, int gx, int gy)
    {
        for (int y = 0; y < shape.GetLength(0); y++)
            for (int x = 0; x < shape.GetLength(1); x++)
                if (shape[y, x] && grid[gy + y, gx + x])
                    return false;
        return true;
    }

    void Place(bool[,] grid, bool[,] shape, int gx, int gy, bool value)
    {
        for (int y = 0; y < shape.GetLength(0); y++)
            for (int x = 0; x < shape.GetLength(1); x++)
                if (shape[y, x])
                    grid[gy + y, gx + x] = value;
    }

    List<bool[,]> GetVariants(bool[,] s)
    {
        List<bool[,]> list = new List<bool[,]>();
        HashSet<string> seen = new HashSet<string>();

        bool[,] cur = s;

        for (int i = 0; i < 4; i++)
        {
            AddIfNew(cur, list, seen);

            bool[,] flipped = Flip(cur);
            AddIfNew(flipped, list, seen);

            cur = Rotate(cur);
        }

        return list;
    }

    void AddIfNew(bool[,] s, List<bool[,]> list, HashSet<string> seen)
    {
        string key = ShapeKey(s);
        if (seen.Add(key))
            list.Add(s);
    }

    string ShapeKey(bool[,] s)
    {
        int h = s.GetLength(0);
        int w = s.GetLength(1);
        char[] chars = new char[h * w];

        int i = 0;
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                chars[i++] = s[y, x] ? '#' : '.';

        return new string(chars);
    }

    bool[,] Rotate(bool[,] s)
    {
        int h = s.GetLength(0);
        int w = s.GetLength(1);
        bool[,] n = new bool[w, h];

        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                n[x, h - y - 1] = s[y, x];

        return n;
    }

    bool[,] Flip(bool[,] s)
    {
        int h = s.GetLength(0);
        int w = s.GetLength(1);
        bool[,] n = new bool[h, w];

        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                n[y, w - x - 1] = s[y, x];

        return n;
    }
}

